import{_ as o,l as i,o as e,c as s,v as r,p as n,x as t,d,i as m,S as p}from"./chunks/framework.InCnrqk-.js";const g=JSON.parse('{"title":"自回归图像生成","description":"","frontmatter":{"title":"自回归图像生成","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/autoregressive-image-gen.md","filePath":"llm/autoregressive-image-gen.md","lastUpdated":1789023840000}'),h={name:"llm/autoregressive-image-gen.md"};function A(_,a,c,f,E,u){const l=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=r('<h1 id="自回归图像生成" tabindex="-1">自回归图像生成 <a class="header-anchor" href="#自回归图像生成" aria-label="Permalink to &quot;自回归图像生成&quot;">​</a></h1><div class="epigraph"><p>把图变成离散码序列之后，图像生成就是语言模型：预测下一个下标，再交给解码器变回像素。</p><footer>—— Esser 等 VQGAN 上的 Transformer；Ramesh 等 DALL·E；Yu 等 Parti</footer></div><p><a href="/llm/cfg-image">上一课</a>在连续潜空间里用 CFG 拉条件。<a href="/llm/vqgan">VQGAN</a> 已给出可感知的码本。缺口是：在这些离散视觉 token 上做 next-token，与文本 LLM 同构。后课 VAR 默认 raster 扫描不是唯一的分解顺序。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>像素 softmax 不可行。量化后长度为 \\(hw\\) 的码序列，因果 Transformer 建模 \\(p(k_{1:hw})\\)。DALL·E 用 dVAE 码 + 文本条件；Parti 把这条路做到更大的编码器–解码器；VQGAN 论文的后半是码上的 GPT。上限仍是 tokenizer 重构天花板：LM 完美，图也回不到比解码器更好。</p><p>扫描顺序默认 raster。竖直邻居在序列上相距一行宽度，与<a href="/llm/2d-rope">2D RoPE</a> 之前理解侧的一维编号是同一扭曲——生成侧会表现为纵向结构难、局部纹理靠码本。</p><p><span class="marginnote">条件可以是文本 token 前缀，不必是 <a href="/llm/llava-projector">LLaVA 投影器</a> 那种连续视觉前缀。理解连续、生成离散，正是后课统一模型要缝的缝。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>先训或冻 tokenizer，再在码上做语言建模，文本为前缀或交叉注意力。采样温度、top-k 与扩散 CFG 不同旋钮：过低温会重复图案。验收：FID + 文本遵守 + 文字可读；不要用 <a href="/llm/clip">CLIP</a> 图文检索单独选 AR 超参。</p>',9)),(e(),n(p,null,{default:t(()=>[m(l,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20TXT%5B%22%E6%96%87%E6%9C%AC%E6%9D%A1%E4%BB%B6%22%5D%20--%3E%20AR%5B%22%E5%9B%A0%E6%9E%9C%20Transformer%22%5D%0A%20%20AR%20--%3E%20IDS%5B%22%E7%A6%BB%E6%95%A3%E7%A0%81%E5%BA%8F%E5%88%97%22%5D%0A%20%20IDS%20--%3E%20DEC%5B%22VQ%20%E8%A7%A3%E7%A0%81%E5%99%A8%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>似然在码上分解为逐步条件。错误会沿 raster 传播：早错一个码，后面整行跟着歪。这与扩散每步改整张潜图不同。因此 AR 对全局布局敏感于开头码，扩散对噪声日程敏感。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>序列长度随分辨率平方涨，双向纹理要靠深注意力补。下一课把「下一步」改成下一尺度，而不是下一格。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>离散码上的 AR 让图像生成与 LLM 同构。</li><li>质量受 VQ 天花板与扫描顺序双重约束。</li><li>与连续扩散是两条接口，不是同一损失。</li><li>出处：VQGAN Transformer；DALL·E；Parti。</li></ul>',6))])}const P=o(h,[["render",A]]);export{g as __pageData,P as default};
